    planName: 'Group Short Term Disability &mdash; Plan A',
    coverageId: 'DIV-011 &middot; Hourly, Ontario'
  };

  var byId = function (id) { return document.getElementById(id); };

  var form = byId('claim-form');
  var panel = byId('member-details');
  var attest = byId('attest');
  var lookupStatus = byId('lookup-status');
  var docsInput = byId('documents');
  var docList = byId('document-list');
  var confirmation = byId('confirmation');
  var steps = byId('steps').getElementsByTagName('li');

  var decode = function (value) {
    var holder = document.createElement('textarea');
    holder.innerHTML = value;
    return holder.value;
  };

  function lookupMember() {
    var policy = byId('policy-number').value.trim();
    var member = byId('member-id').value.trim();

    if (!policy || !member) {
      lookupStatus.className = 'lookup-status';
      lookupStatus.textContent = 'Enter both a policy number and a member id to look up the member.';
      return;
    }

    var record = DIRECTORY[policy.toUpperCase() + '|' + member.toUpperCase()] || FALLBACK;

    byId('member-name').value = decode(record.memberName);
    byId('member-dob').value = record.memberDob;
    byId('member-email').value = decode(record.memberEmail);
    byId('job-title').value = decode(record.jobTitle);
    byId('hire-date').value = record.hireDate;
    byId('annual-earnings').value = decode(record.annualEarnings);
    byId('plan-name').value = decode(record.planName);
    byId('coverage-id').value = decode(record.coverageId);

    panel.hidden = false;
    attest.disabled = false;
    attest.required = true;

    lookupStatus.className = 'lookup-status ok';
    lookupStatus.textContent = 'Member found: ' + decode(record.memberName) + ' on ' + decode(record.planName) + '. Review the details below before submitting.';

    setStep(1);
    panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function setStep(index) {
    for (var i = 0; i < steps.length; i++) {
      if (i <= index) {
        steps[i].className = 'on';
      } else {
        steps[i].className = '';
      }
    }
  }

  function renderFiles() {
    var files = docsInput.files;
    docList.innerHTML = '';

    if (!files || files.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty';
      empty.textContent = 'No documents attached yet.';
      docList.appendChild(empty);
      return;
    }

    for (var i = 0; i < files.length; i++) {
      var row = document.createElement('li');
      var name = document.createElement('span');
      name.textContent = files[i].name;
      var size = document.createElement('span');
      size.className = 'size';
      size.textContent = Math.max(1, Math.round(files[i].size / 1024)) + ' KB';
      row.appendChild(name);
      row.appendChild(size);
      docList.appendChild(row);
    }

    setStep(3);
  }

  function reference() {
    var now = new Date();
    var month = String(now.getMonth() + 1);
    if (month.length === 1) { month = '0' + month; }
    var serial = String(Math.floor(1000 + Math.random() * 9000));
    return 'MS-' + now.getFullYear() + '-' + month + '-' + serial;
  }

  function documentSummary() {
    var files = docsInput.files;
    if (!files || files.length === 0) { return 'None attached'; }
    var names = [];
    for (var i = 0; i < files.length; i++) { names.push(files[i].name); }
    return files.length + (files.length === 1 ? ' document: ' : ' documents: ') + names.join(', ');
  }

  function submit(event) {
    event.preventDefault();

    byId('reference-number').textContent = reference();
    byId('submission-status').textContent = 'Received';
    byId('sum-member').textContent = byId('member-name').value || 'Not provided';
    byId('sum-policy').textContent = byId('policy-number').value + ' / ' + byId('member-id').value;
    byId('sum-nature').textContent = byId('nature-of-absence').value || 'Not provided';
    byId('sum-absent').textContent = byId('first-day-absent').value || 'Not provided';
    byId('sum-docs').textContent = documentSummary();
    byId('sum-when').textContent = new Date().toLocaleString();

    form.hidden = true;
    confirmation.hidden = false;
    setStep(4);
    window.scrollTo(0, 0);
  }

  byId('lookup-btn').addEventListener('click', lookupMember);
  docsInput.addEventListener('change', renderFiles);
  form.addEventListener('submit', submit);
  byId('new-claim').addEventListener('click', function () { window.location.reload(); });
})();
</script>

